WITH not_flagged AS (SELECT s.* FROM orders s WHERE EXISTS (SELECT 1 FROM order_items x WHERE x.order_id = s.id AND x.order_id IN (18, 21, 40))) SELECT CASE WHEN shipping_fee >= 34 THEN 'HIGH' ELSE 'LOW' END AS shipping_fee_tier, SORT_ARRAY(COLLECT_SET(channel)) AS channel_list, SORT_ARRAY(COLLECT_SET(channel)) AS channel_list_2, ROUND(AVG(amount), 2) AS avg_amount FROM not_flagged GROUP BY CASE WHEN shipping_fee >= 34 THEN 'HIGH' ELSE 'LOW' END ORDER BY avg_amount NULLS FIRST;
